mkdir -p .semserve/g1_checks && cat > .semserve/g1_checks/test_branch.py <<'EOF'
import unittest, json, sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', '..', 'components', 'crew_compatibility'))
from work import compute

class TestCrewCompat(unittest.TestCase):
    def test_shape_and_order(self):
        payload = {
            "vehicles": [
                {"id": "v1", "type": "bulk", "capacity": 3, "cost": 1},
                {"id": "v2", "type": "bulk", "capacity": 2, "cost": 2},
            ],
            "drivers": [
                {"id": "d1", "types": ["bulk"], "max_work": 4, "max_continuous": 2, "break": 1},
                {"id": "d2", "types": ["bulk"], "max_work": 3, "max_continuous": 3, "break": 2},
            ],
        }
        out = compute(payload)
        self.assertEqual(out, {"v1": ["d1", "d2"], "v2": ["d1", "d2"]})

    def test_type_filter_and_order(self):
        payload = {
            "vehicles": [
                {"id": "v1", "type": "bulk", "capacity": 3, "cost": 1},
                {"id": "v2", "type": "express", "capacity": 2, "cost": 2},
            ],
            "drivers": [
                {"id": "d1", "types": ["express"], "max_work": 4, "max_continuous": 2, "break": 1},
                {"id": "d2", "types": ["bulk", "express"], "max_work": 3, "max_continuous": 3, "break": 2},
                {"id": "d3", "types": ["bulk"], "max_work": 3, "max_continuous": 3, "break": 2},
            ],
        }
        out = compute(payload)
        self.assertEqual(out["v1"], ["d2", "d3"])
        self.assertEqual(out["v2"], ["d1", "d2"])

if __name__ == "__main__":
    unittest.main()
EOF
